#!/bin/bash
# Mentat 2.0.0 installer: Claude Code cost in the macOS menu bar (Apple Silicon, macOS 12+).
# Nothing else to install.
# Usage:  bash install.sh            install or update
#         bash install.sh uninstall  remove
set -euo pipefail
DIR="$HOME/.config/mentat"
PLIST="$HOME/Library/LaunchAgents/com.mentat.plist"
LABEL="com.mentat"

stop_app() {
  launchctl bootout "gui/$(id -u)/$LABEL" 2>/dev/null || true
  pkill -x Mentat 2>/dev/null || true
}

if [ "${1:-}" = "uninstall" ]; then
  stop_app
  rm -f "$PLIST"
  rm -rf "$DIR" "$HOME/Library/Logs/Mentat"
  echo "Mentat removed."
  exit 0
fi

[ "$(uname -s)" = "Darwin" ] || { echo "Mentat needs macOS."; exit 1; }
[ "$(sysctl -n hw.optional.arm64 2>/dev/null || echo 0)" = "1" ] || { echo "Mentat needs a Mac with Apple Silicon."; exit 1; }
[ "$(sw_vers -productVersion | cut -d. -f1)" -ge 12 ] || { echo "Mentat needs macOS 12 or newer."; exit 1; }

mkdir -p "$DIR"
rm -f "$DIR/usage.py"
rm -rf "$DIR/src"

# Keep the user's own settings when updating.
if [ ! -f "$DIR/config.json" ]; then
cat > "$DIR/config.json" <<'MENTAT_CONFIG'
{
  "refresh_seconds": 300,
  "monthly_limit": 600,
  "title": "${today} / ${month} ({pct}) / ${limit}",
  "windows": [
    "5h",
    "today",
    "7d",
    "month"
  ],
  "cache_write_5m_multiplier": 1.25,
  "cache_write_1h_multiplier": 2.0,
  "prices_note": "USD per 1M tokens: [input, output, cache_read]. Longest model-name prefix wins. Verify against the Anthropic pricing page.",
  "alert_percent": {
    "yellow": 70,
    "orange": 80,
    "red": 90
  },
  "prices": {
    "claude-fable-5": [
      10.0,
      50.0,
      0.25
    ],
    "claude-opus-5-5": [
      4.0,
      20.0,
      0.2
    ],
    "claude-opus-5": [
      5.0,
      25.0,
      0.5
    ],
    "claude-opus-4": [
      5.0,
      25.0,
      0.5
    ],
    "claude-sonnet-5": [
      2.0,
      10.0,
      0.2
    ],
    "claude-sonnet-4": [
      3.0,
      15.0,
      0.3
    ],
    "claude-haiku-5-5": [
      0.1,
      0.5,
      0.01
    ],
    "claude-haiku-4": [
      1.0,
      5.0,
      0.1
    ]
  }
}
MENTAT_CONFIG
fi

if [ -z "${MENTAT_NO_LAUNCH:-}" ]; then stop_app; fi
base64 -D <<'MENTAT_BINARY' | gunzip > "$DIR/Mentat.tmp"
